<script setup lang="ts">
import { onMounted, ref, computed } from 'vue'
import { profileApi } from '../api/profile'
import { tradingApi } from '../api/trading'
import { riskApi } from '../api/risk'
import PaginationBar from '../components/PaginationBar.vue'

const q=ref('');const tier=ref('');const customerType=ref('');const items=ref<any[]>([]);const selected=ref<any>(null);const orders=ref<any[]>([]);const orderTotal=ref(0);const orderPage=ref(1);const orderPageSize=ref(10);const loading=ref(true);const error=ref('');const message=ref('');const working=ref(false);const releaseNote=ref('风险复核后解除交易限制');const page=ref(1);const pageSize=ref(10);const total=ref(0);const pages=computed(()=>Math.max(1,Math.ceil(total.value/pageSize.value)))
async function load(){loading.value=true;try{const r=(await profileApi.customers(q.value,tier.value,customerType.value,pageSize.value,(page.value-1)*pageSize.value)).data.data;items.value=r.items;total.value=r.total}catch(e:any){error.value=e.response?.data?.detail||e.message}finally{loading.value=false}}
function search(){page.value=1;load()}function changeSize(n:number){pageSize.value=n;page.value=1;load()}function go(n:number){page.value=Math.min(Math.max(n,1),pages.value);load()}
async function openCustomer(id:string){try{selected.value=(await profileApi.managedCustomer(id)).data.data;orderPage.value=1;const data=(await tradingApi.customerOrders(id,orderPageSize.value,0)).data.data;orders.value=data.items;orderTotal.value=data.total}catch(e:any){error.value=e.response?.data?.detail||e.message}}
async function loadCustomerOrders(){if(!selected.value)return;try{const data=(await tradingApi.customerOrders(selected.value.user.id,orderPageSize.value,(orderPage.value-1)*orderPageSize.value)).data.data;orders.value=data.items;orderTotal.value=data.total}catch(e:any){error.value=e.response?.data?.detail||e.message}}
async function releaseRestriction(){if(!selected.value?.risk_operation?.latest_alert_id)return;working.value=true;error.value='';message.value='';try{await riskApi.action(selected.value.risk_operation.latest_alert_id,{action_code:'RELEASE_RESTRICTION',note:releaseNote.value||'风险复核后解除交易限制'});await openCustomer(selected.value.user.id);await load();message.value='已解除交易限制；预警仍保持风险关注，需在风险预警页继续完成调查与结案。'}catch(e:any){error.value=e.response?.data?.detail?.message||e.response?.data?.detail||e.message}finally{working.value=false}}
function orderGo(n:number){orderPage.value=Math.max(1,n);loadCustomerOrders()}
function orderChangeSize(n:number){orderPageSize.value=n;orderPage.value=1;loadCustomerOrders()}
const tierText:Record<string,string>={ordinary:'普通客户',gold:'黄金客户',platinum:'白金客户',diamond:'钻石客户',private_bank:'私人银行',enterprise_standard:'企业标准'}
const operationRiskText:Record<string,string>={normal:'正常',monitoring:'风险关注',restricted:'交易限制'}
onMounted(load)
</script>
<template><section class="table-module"><div class="module-header"><div><span class="module-kicker">CUSTOMER MANAGEMENT</span><h2>客户管理</h2></div><div class="module-tools"><input v-model="q" placeholder="搜索用户名或姓名" @keyup.enter="search"/><select v-model="customerType" @change="search"><option value="">全部客户类型</option><option value="individual">个人客户</option><option value="enterprise">企业客户</option></select><select v-model="tier" @change="search"><option value="">全部层级</option><option value="ordinary">普通</option><option value="gold">黄金</option><option value="platinum">白金</option><option value="diamond">钻石</option><option value="private_bank">私人银行</option></select><button class="button" @click="search">搜索</button></div></div><p v-if="error" class="error">{{error}}</p><p v-if="message" class="success">{{message}}</p><div v-if="loading" class="empty">正在读取客户…</div><div v-else class="module-table-wrap customer-management-table"><table class="admin-table"><thead><tr><th>用户名</th><th>姓名</th><th>投资目标</th><th>总资产</th><th>客户类型</th><th>客户层级</th><th>持仓</th><th>操作风控</th><th>状态</th><th>操作</th></tr></thead><tbody><tr v-for="customer in items" :key="customer.id"><td>{{customer.username}}</td><td>{{customer.display_name}}</td><td>{{customer.profile?.investment_goal||'—'}}</td><td>¥{{customer.latest_asset?.total_asset??0}}</td><td>{{customer.profile?.customer_type==='enterprise'?'企业客户':'个人客户'}}</td><td><span class="pill">{{tierText[customer.customer_tier]||customer.customer_tier}}</span></td><td>{{customer.holding_count}}</td><td><span class="pill" :class="'risk-'+(customer.risk_operation_status||'normal')">{{operationRiskText[customer.risk_operation_status]||'正常'}}</span><small v-if="customer.latest_risk_rule_code" class="audit-sub">{{customer.latest_risk_rule_code}}</small></td><td>{{customer.status}}</td><td><button class="table-action" @click="openCustomer(customer.id)">查看详情</button></td></tr><tr v-if="!items.length"><td colspan="10" class="table-empty">暂无客户</td></tr></tbody></table></div><PaginationBar :page="page" :page-size="pageSize" :total="total" @change="go" @size-change="changeSize"/><div v-if="selected" class="admin-modal-backdrop" @click.self="selected=null"><div class="admin-modal customer-modal"><h3>{{selected.user?.display_name}} · 客户详情</h3><p>用户名：{{selected.user?.username}}</p><p>总资产：¥{{selected.latest_asset?.total_asset??0}} · 可投资资产：¥{{selected.latest_asset?.investable_asset??0}}</p><p>操作风控：<strong>{{operationRiskText[selected.risk_operation?.status]||'正常'}}</strong><span v-if="selected.risk_operation?.latest_rule_code"> · {{selected.risk_operation.latest_rule_code}}（{{selected.risk_operation.latest_alert_level||'—'}}）</span><span v-if="selected.risk_operation?.restriction_reason"> · {{selected.risk_operation.restriction_reason}}</span></p><div v-if="selected.risk_operation?.restriction_status==='restricted'" class="operation-restriction-note"><span>该客户当前已限制交易。解除后仍会保留风险关注，直至风险预警正式结案。</span><label>解除说明<input v-model="releaseNote" :disabled="working" maxlength="500"></label><button class="table-action" :disabled="working" @click="releaseRestriction">{{working?'解除中…':'解除交易限制'}}</button></div><h4>订单</h4><table class="admin-table"><thead><tr><th>订单号</th><th>产品</th><th>金额</th><th>状态</th></tr></thead><tbody><tr v-for="order in orders" :key="order.id"><td>{{order.order_no}}</td><td>{{order.product_name||order.product_id}}</td><td>¥{{order.amount}}</td><td>{{order.status}}</td></tr></tbody></table><PaginationBar :page="orderPage" :page-size="orderPageSize" :total="orderTotal" @change="orderGo" @size-change="orderChangeSize"/><button class="button" @click="selected=null">关闭</button></div></div></section></template>
